<script setup>
import {ref,onMounted,onBeforeUnmount,provide} from 'vue';
import {createClient,prepareSave,errorText} from './client.mjs';
import {contract,clone,clean,validate} from './schema.mjs';
import {label} from './labels.mjs';
import {useStatus} from './status.mjs';
import Status from './Status.vue';import Field from './Field.vue';
import './style.css';
const props=defineProps({api:{type:Object,required:true},pluginId:{type:String,required:true},sourcePluginId:String,initialConfig:{type:Object,default:()=>({})}});
const emit=defineEmits(['save','close','switch']);
const client=createClient(props.api,props.pluginId,props.sourcePluginId),status=useStatus(client);
const draft=ref(null),errors=ref([]),busy=ref(false),submitted=ref(false),group=ref('ownership'),catalog=ref(null),continuation=ref(null),continuationId=ref(''),continuationKind=ref('operation');let mounted=true;
const catalogs=ref({});provide('subscribetter:catalogs',catalogs);
const groups=[['ownership','纳管与宿主影响',['enabled','dry_run','auto_types','passive_libraries','destination_templates','enhance_host_meta','meta_protected_names']],['policy','独立策略',['policy']],['lifecycle','生命周期',['lifecycle']],['candidates','站点与搜索',['candidates']],['schedule','观察、冷却、抢占',['schedule']],['delivery','交付与映射',['delivery']],['recovery','扫描与恢复',['recovery']],['permissions','五项清理权限',['permissions']],['safety','安全与容量',['safety']],['discovery','榜单与 RSS',['discovery','history_view']],['ai','AI 与独立聊天',['ai_assist']]];
async function refresh(){const c=await status.refresh();if(c&&mounted){draft.value=clean(contract.schemas.Config,clone(c.config));continuation.value=null;submitted.value=false;errors.value=[];try{const [result,routes]=await Promise.all([client.get('/configuration/categories'),client.get('/discovery/catalog')]);if(mounted){catalog.value=result;catalogs.value={route_key:(routes.result?.routes||[]).map(r=>({value:r.key,title:r.label+' · '+r.key}))};}}catch(e){if(mounted)errors.value=[errorText(e)];}}}
async function loadContinuation(){busy.value=true;errors.value=[];try{let result;if(continuationKind.value==='operation'){const op=await client.get('/management/operations/'+encodeURIComponent(continuationId.value));const p=op.result?.configuration;if(op.state!=='APPLIED'||!op.result?.native_save_required||!p?.valid||p.revision!==status.current.value.revision)throw Error('STALE_OPERATION');result={config:p.config,base:status.current.value.digest,kind:'operation'};}else{const r=await client.get('/migration/receipts/'+encodeURIComponent(continuationId.value));if(r.state==='READY_CONFIG'&&r.base_digest===status.current.value.digest&&r.proposed_config){result={config:r.proposed_config,base:r.base_digest,kind:'cutover',receipt_id:r.receipt_id}}else if(r.state==='ROLLBACK_FENCED'){const change=r.next_changes.find(c=>c.instance_id===props.pluginId);if(!change||change.expected_digest!==status.current.value.digest)throw Error('STALE_ROLLBACK');const config=clone(status.current.value.config);for(const [key,value] of Object.entries(change.changes))config[key]=typeof value==='object'?{...config[key],...value}:value;draft.value=config;continuation.value=null;return;}else throw Error('CUTOVER_NOT_READY');}if(mounted){continuation.value=result;draft.value=clone(result.config);submitted.value=false;}}catch(e){if(mounted)errors.value=[errorText(e)]}finally{if(mounted)busy.value=false}}
async function save(){if(busy.value||submitted.value||!draft.value||status.error.value)return;errors.value=validate(contract.schemas.Config,draft.value);if(errors.value.length)return;busy.value=true;
  try{if(continuation.value){const c=await client.get('/configuration');if(c.digest!==continuation.value.base)throw Error('STALE_CONFIGURATION');if(continuation.value.kind==='cutover'){const r=await client.get('/migration/receipts/'+encodeURIComponent(continuation.value.receipt_id));if(r.state!=='READY_CONFIG'||r.base_digest!==c.digest||JSON.stringify(r.proposed_config)!==JSON.stringify(continuation.value.config))throw Error('STALE_CUTOVER');}if(mounted){submitted.value=true;emit('save',clone(continuation.value.config));}}else await prepareSave(client,status.current.value,clean(contract.schemas.Config,draft.value),config=>{if(mounted){submitted.value=true;emit('save',config);}})}catch(e){if(mounted)errors.value=e.validationErrors||[errorText(e)];}finally{if(mounted)busy.value=false;}}
onMounted(refresh);onBeforeUnmount(()=>{mounted=false;draft.value=null;errors.value=[]});
</script>
<template><section class="sb-root" aria-label="subscriBetter 配置"><h2>subscriBetter 配置</h2><Status :status="status"/>
  <p>关闭普通工作仍保留已受管任务的安全隔离。公共解析包装可能影响未受管流程；AI 桥接与聊天须独立授权和唯一响应者回执。</p>
  <p>服务引用必须来自已有宿主配置。<a href="/#/setting">打开宿主设置</a> · 密钥在管理页的私密写入操作中配置。</p>
  <div class="sb-actions"><VBtn variant="tonal" :disabled="busy" @click="refresh">刷新当前值（丢弃未保存编辑）</VBtn><VBtn variant="text" @click="emit('switch')">打开管理页</VBtn></div>
  <details><summary>从提示词操作 / 切换回执继续宿主 Save</summary><p>已预检的配置保持不可修改，使用服务器原回执，不生成替代配置。回退隔离变更仍会正常预检。</p><select v-model="continuationKind" aria-label="回执类型"><option value="operation">提示词恢复操作 ID</option><option value="cutover">READY_CONFIG / 回退切换回执 ID</option></select><input v-model="continuationId" aria-label="回执 ID"><button :disabled="busy||!continuationId||!status.current.value" @click="loadContinuation">加载回执配置</button><p v-if="continuation">已加载服务器预检配置。刷新当前值可放弃本次继续操作。</p></details>
  <nav class="sb-nav" aria-label="配置分组"><button v-for="g in groups" :key="g[0]" :aria-current="group===g[0]" @click="group=g[0]">{{g[1]}}</button></nav>
  <template v-if="draft"><div v-for="g in groups" :key="g[0]" v-show="group===g[0]"><h3>{{g[1]}}</h3><p v-if="g[0]==='policy'&&catalog" class="sb-muted">当前分类发布版本 {{catalog.revision}}；分类绑定只接受启用且类型匹配的真实 ID。</p><ul v-if="g[0]==='policy'&&catalog"><li v-for="c in catalog.categories" :key="c.id">{{c.name}} · {{c.media_type}} · {{c.id}} · {{c.enabled?'启用':'关闭'}}</li></ul><p v-if="g[0]==='permissions'">每项权限独立，默认关闭；同时需要对应规则的同名权限。取消交付本身不删除文件或下载器任务。</p><p v-if="g[0]==='delivery'">映射① Emby 路径 → MP 可读 STRM；映射② STRM 目标 → CD2 内部路径。保留 SSA / VTT / SUP / ZIP 与路径安全；不处理 IDX/SUB、独立字体或许可证附件。</p><Field v-for="key in g[2]" :key="key" :schema="contract.schemas.Config.properties[key]" :name="key" :model-value="draft[key]" :readonly="busy||submitted||!!continuation" @update:model-value="draft[key]=$event"/></div></template>
  <ul v-if="errors.length" role="alert" class="sb-error"><li v-for="e in errors" :key="e">{{e}}</li></ul><p v-if="submitted" role="status">已提交预检后的完整配置给宿主 Save。结果待下次打开或刷新当前状态核对。</p>
  <div class="sb-actions"><VBtn color="primary" :loading="busy" :disabled="!draft||submitted||!!status.error.value" @click="save">{{continuation?'提交原回执配置给宿主 Save':'预检并提交宿主 Save'}}</VBtn><VBtn variant="text" @click="emit('close')">关闭</VBtn></div>
</section></template>
